ALTER TABLE public.transactions ADD CONSTRAINT transactions_org_id_id_key UNIQUE(org_id,id);
ALTER TABLE public.alerts ADD CONSTRAINT alerts_org_id_id_key UNIQUE(org_id,id);
CREATE TABLE public.monitoring_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES public.organizations(id),kind text NOT NULL CHECK(kind IN ('expense','budget','cash','supplier','inventory','control')),label text NOT NULL,record_date date NOT NULL,currency text NOT NULL DEFAULT 'ZAR',payload jsonb NOT NULL DEFAULT '{}',transaction_id uuid,replaces_id uuid UNIQUE,created_by uuid NOT NULL DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(org_id,id),FOREIGN KEY(org_id,transaction_id) REFERENCES public.transactions(org_id,id),FOREIGN KEY(org_id,replaces_id) REFERENCES public.monitoring_records(org_id,id));
GRANT SELECT,INSERT ON public.monitoring_records TO authenticated;
GRANT ALL ON public.monitoring_records TO service_role;
ALTER TABLE public.monitoring_records ENABLE ROW LEVEL SECURITY;
CREATE POLICY monitoring_read ON public.monitoring_records FOR SELECT TO authenticated USING(public.has_org_role(org_id,auth.uid(),ARRAY['admin','financial_manager','auditor']::public.org_role[]));
CREATE POLICY monitoring_insert ON public.monitoring_records FOR INSERT TO authenticated WITH CHECK(created_by=auth.uid() AND public.has_org_role(org_id,auth.uid(),ARRAY['admin','financial_manager']::public.org_role[]));
CREATE TABLE public.investigations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES public.organizations(id),alert_id uuid NOT NULL,title text NOT NULL,status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','investigating','closed')),assigned_to uuid,outcome text NOT NULL DEFAULT '',evidence_snapshot jsonb NOT NULL DEFAULT '{}',created_by uuid NOT NULL DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(org_id,id),UNIQUE(org_id,alert_id),FOREIGN KEY(org_id,alert_id) REFERENCES public.alerts(org_id,id));
GRANT SELECT,INSERT,UPDATE ON public.investigations TO authenticated;
GRANT ALL ON public.investigations TO service_role;
ALTER TABLE public.investigations ENABLE ROW LEVEL SECURITY;
CREATE POLICY cases_read ON public.investigations FOR SELECT TO authenticated USING(public.has_org_role(org_id,auth.uid(),ARRAY['admin','financial_manager','auditor']::public.org_role[]));
CREATE POLICY cases_insert ON public.investigations FOR INSERT TO authenticated WITH CHECK(created_by=auth.uid() AND public.has_org_role(org_id,auth.uid(),ARRAY['admin','financial_manager']::public.org_role[]));
CREATE POLICY cases_update ON public.investigations FOR UPDATE TO authenticated USING(public.has_org_role(org_id,auth.uid(),ARRAY['admin','financial_manager']::public.org_role[])) WITH CHECK(public.has_org_role(org_id,auth.uid(),ARRAY['admin','financial_manager']::public.org_role[]));
CREATE TABLE public.investigation_notes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,case_id uuid NOT NULL,body text NOT NULL CHECK(length(trim(body)) BETWEEN 1 AND 10000),created_by uuid NOT NULL DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(org_id,case_id) REFERENCES public.investigations(org_id,id));
GRANT SELECT,INSERT ON public.investigation_notes TO authenticated;
GRANT ALL ON public.investigation_notes TO service_role;
ALTER TABLE public.investigation_notes ENABLE ROW LEVEL SECURITY;
CREATE POLICY notes_read ON public.investigation_notes FOR SELECT TO authenticated USING(public.has_org_role(org_id,auth.uid(),ARRAY['admin','financial_manager','auditor']::public.org_role[]));
CREATE POLICY notes_insert ON public.investigation_notes FOR INSERT TO authenticated WITH CHECK(created_by=auth.uid() AND public.has_org_role(org_id,auth.uid(),ARRAY['admin','financial_manager']::public.org_role[]));
CREATE TABLE public.evidence_documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,case_id uuid,record_id uuid,storage_path text NOT NULL UNIQUE,filename text NOT NULL,created_by uuid NOT NULL DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now(),CHECK((case_id IS NULL)<>(record_id IS NULL)),FOREIGN KEY(org_id,case_id) REFERENCES public.investigations(org_id,id),FOREIGN KEY(org_id,record_id) REFERENCES public.monitoring_records(org_id,id),CHECK(split_part(storage_path,'/',1)=org_id::text));
GRANT SELECT,INSERT ON public.evidence_documents TO authenticated;
GRANT ALL ON public.evidence_documents TO service_role;
ALTER TABLE public.evidence_documents ENABLE ROW LEVEL SECURITY;
CREATE POLICY evidence_read ON public.evidence_documents FOR SELECT TO authenticated USING(public.has_org_role(org_id,auth.uid(),ARRAY['admin','financial_manager','auditor']::public.org_role[]));
CREATE POLICY evidence_insert ON public.evidence_documents FOR INSERT TO authenticated WITH CHECK(created_by=auth.uid() AND public.has_org_role(org_id,auth.uid(),ARRAY['admin','financial_manager']::public.org_role[]));
CREATE TABLE public.audit_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES public.organizations(id),actor_id uuid,entity text NOT NULL,entity_id uuid NOT NULL,action text NOT NULL,before_data jsonb,after_data jsonb,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.audit_events TO authenticated;
GRANT ALL ON public.audit_events TO service_role;
ALTER TABLE public.audit_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY audit_read ON public.audit_events FOR SELECT TO authenticated USING(public.has_org_role(org_id,auth.uid(),ARRAY['admin','financial_manager','auditor']::public.org_role[]));
ALTER TABLE public.alerts ADD COLUMN monitoring_record_id uuid,ADD COLUMN detection_key text;
ALTER TABLE public.alerts ADD CONSTRAINT alerts_monitoring_tenant_fk FOREIGN KEY(org_id,monitoring_record_id) REFERENCES public.monitoring_records(org_id,id);
CREATE UNIQUE INDEX alerts_detection_key ON public.alerts(org_id,detection_key);
CREATE INDEX monitoring_org_kind ON public.monitoring_records(org_id,kind,record_date);
CREATE INDEX audit_org_time ON public.audit_events(org_id,created_at DESC);
CREATE FUNCTION public.reject_immutable_change() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN RAISE EXCEPTION 'This history is immutable; append a correction instead'; END $$;
CREATE TRIGGER immutable_records BEFORE UPDATE OR DELETE ON public.monitoring_records FOR EACH ROW EXECUTE FUNCTION public.reject_immutable_change();
CREATE TRIGGER immutable_notes BEFORE UPDATE OR DELETE ON public.investigation_notes FOR EACH ROW EXECUTE FUNCTION public.reject_immutable_change();
CREATE TRIGGER immutable_evidence BEFORE UPDATE OR DELETE ON public.evidence_documents FOR EACH ROW EXECUTE FUNCTION public.reject_immutable_change();
CREATE TRIGGER immutable_audit BEFORE UPDATE OR DELETE ON public.audit_events FOR EACH ROW EXECUTE FUNCTION public.reject_immutable_change();
CREATE FUNCTION public.validate_monitoring_revision() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE p public.monitoring_records; BEGIN IF NEW.replaces_id IS NOT NULL THEN SELECT * INTO p FROM public.monitoring_records WHERE id=NEW.replaces_id AND org_id=NEW.org_id; IF NOT FOUND OR p.kind<>NEW.kind THEN RAISE EXCEPTION 'Correction must replace a record of the same kind and business'; END IF; END IF; IF NEW.kind='supplier' AND (NEW.payload->>'bank_approved')='yes' AND NOT public.has_org_role(NEW.org_id,auth.uid(),ARRAY['admin']::public.org_role[]) THEN RAISE EXCEPTION 'Only administrators can approve supplier banking details'; END IF; RETURN NEW; END $$;
CREATE TRIGGER monitoring_revision_check BEFORE INSERT ON public.monitoring_records FOR EACH ROW EXECUTE FUNCTION public.validate_monitoring_revision();
CREATE FUNCTION public.validate_case() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND (NEW.org_id<>OLD.org_id OR NEW.alert_id<>OLD.alert_id OR NEW.created_by<>OLD.created_by OR NEW.evidence_snapshot<>OLD.evidence_snapshot) THEN RAISE EXCEPTION 'Case business, source and original evidence cannot change'; END IF; IF NEW.status='closed' AND length(trim(NEW.outcome))<3 THEN RAISE EXCEPTION 'A documented outcome is required before closing a case'; END IF; IF NEW.assigned_to IS NOT NULL AND NOT public.has_org_role(NEW.org_id,NEW.assigned_to,ARRAY['admin','financial_manager','auditor']::public.org_role[]) THEN RAISE EXCEPTION 'Assignee must be an authorised member of this business'; END IF; IF TG_OP='INSERT' THEN SELECT jsonb_build_object('alert',to_jsonb(a),'transaction',to_jsonb(t),'record',to_jsonb(r)) INTO NEW.evidence_snapshot FROM public.alerts a LEFT JOIN public.transactions t ON t.id=a.transaction_id AND t.org_id=a.org_id LEFT JOIN public.monitoring_records r ON r.id=a.monitoring_record_id AND r.org_id=a.org_id WHERE a.id=NEW.alert_id AND a.org_id=NEW.org_id; END IF; NEW.updated_at=now(); RETURN NEW; END $$;
CREATE TRIGGER validate_investigation BEFORE INSERT OR UPDATE ON public.investigations FOR EACH ROW EXECUTE FUNCTION public.validate_case();
CREATE FUNCTION public.capture_financial_audit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v jsonb; BEGIN IF TG_OP='DELETE' THEN v=to_jsonb(OLD); ELSE v=to_jsonb(NEW); END IF; INSERT INTO public.audit_events(org_id,actor_id,entity,entity_id,action,before_data,after_data) VALUES((v->>'org_id')::uuid,auth.uid(),TG_TABLE_NAME,(v->>'id')::uuid,TG_OP,CASE WHEN TG_OP<>'INSERT' THEN to_jsonb(OLD) END,CASE WHEN TG_OP<>'DELETE' THEN to_jsonb(NEW) END); IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
CREATE TRIGGER audit_transactions AFTER INSERT OR UPDATE OR DELETE ON public.transactions FOR EACH ROW EXECUTE FUNCTION public.capture_financial_audit();
CREATE TRIGGER audit_alerts AFTER INSERT OR UPDATE OR DELETE ON public.alerts FOR EACH ROW EXECUTE FUNCTION public.capture_financial_audit();
CREATE TRIGGER audit_monitoring AFTER INSERT ON public.monitoring_records FOR EACH ROW EXECUTE FUNCTION public.capture_financial_audit();
CREATE TRIGGER audit_cases AFTER INSERT OR UPDATE ON public.investigations FOR EACH ROW EXECUTE FUNCTION public.capture_financial_audit();
CREATE TRIGGER audit_notes AFTER INSERT ON public.investigation_notes FOR EACH ROW EXECUTE FUNCTION public.capture_financial_audit();
CREATE TRIGGER audit_documents AFTER INSERT ON public.evidence_documents FOR EACH ROW EXECUTE FUNCTION public.capture_financial_audit();
CREATE POLICY fiq_evidence_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='fiq-evidence' AND public.has_org_role((storage.foldername(name))[1]::uuid,auth.uid(),ARRAY['admin','financial_manager','auditor']::public.org_role[]));
CREATE POLICY fiq_evidence_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='fiq-evidence' AND public.has_org_role((storage.foldername(name))[1]::uuid,auth.uid(),ARRAY['admin','financial_manager']::public.org_role[]));